#!/usr/bin/env bash
#
# Builds a release APK with every supported ABI and verifies it.
#
# The native project in `android/` is generated by `expo prebuild` and is not
# committed. This script regenerates it, builds the release variant, and runs
# the ABI check so a partial build fails here rather than on a device.
#
# Environment:
#   ANDROID_HOME  Android SDK root (required by Gradle)
#   ANDROID_ARCHITECTURES  space-separated ABI list (default: all supported)
#
# Usage: build-release.sh [--no-prebuild] [--debug]

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT"

PREBUILD=1
VARIANT="release"
while [[ $# -gt 0 ]]; do
  case "$1" in
    --no-prebuild) PREBUILD=0; shift ;;
    --debug) VARIANT="debug"; shift ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

ALL_ABIS=(arm64-v8a armeabi-v7a x86 x86_64)
if [[ -n "${ANDROID_ARCHITECTURES:-}" ]]; then
  read -r -a ALL_ABIS <<< "$ANDROID_ARCHITECTURES"
fi

: "${ANDROID_HOME:?ANDROID_HOME must be set}"

if [[ $PREBUILD -eq 1 ]]; then
  echo "==> Generating the native Android project"
  npx expo prebuild --platform android --no-install
fi

# Every ABI is compiled on every run. Restricting the architecture leaves the
# other ABIs without their native libraries, and the resulting APK crashes on
# launch for anyone whose device is not the one that was built.
echo "==> Building ${VARIANT} APK for: ${ALL_ABIS[*]}"
(
  cd android
  ./gradlew "assemble${VARIANT^}" \
    --no-daemon \
    "-PreactNativeArchitectures=$(IFS=,; echo "${ALL_ABIS[*]}")"
)

APK="android/app/build/outputs/apk/${VARIANT}/app-release.apk"
if [[ $VARIANT == "debug" ]]; then
  APK="android/app/build/outputs/apk/debug/app-debug.apk"
fi

if [[ ! -f "$APK" ]]; then
  echo "error: expected APK at $APK" >&2
  exit 1
fi

echo "==> Verifying native libraries"
scripts/android/verify-apk.sh "$APK" "${ALL_ABIS[@]}"

echo "==> APK: $APK"
